const MW_resH=(x1,y,x2,col=INK)=>{const n=6,d=(x2-x1)/(n+2);let p=[`${x1},${y}`,`${x1+d},${y}`];for(let i=0;i<n;i++)p.push(`${(x1+d*(1.5+i)).toFixed(1)},${y+(i%2?10:-10)}`);p.push(`${x2-d},${y}`,`${x2},${y}`);return MW_pl(p.join(' '),col,3)};
const MW_resV=(x,y1,y2,col=INK)=>{const n=6,d=(y2-y1)/(n+2);let p=[`${x},${y1}`,`${x},${y1+d}`];for(let i=0;i<n;i++)p.push(`${x+(i%2?10:-10)},${(y1+d*(1.5+i)).toFixed(1)}`);p.push(`${x},${y2-d}`,`${x},${y2}`);return MW_pl(p.join(' '),col,3)};
