 ang.forEach((d,i)=>{const a=d*Math.PI/180;q+=MW_L(cx+R*Math.cos(a),cy+R*Math.sin(a),cx+A*Math.cos(a),cy+A*Math.sin(a),INK,6)+MW_badge(+(cx+B*Math.cos(a)).toFixed(1),+(cy+B*Math.sin(a)).toFixed(1),String(i+1),o.bc,o.bo,15)});
