const MW_wilk=(x0,x1,x2,y,h,o={})=>MW_L(x0,y,x0+70,y,INK,5)+MW_pl(`${x0+70},${y} ${x0+100},${y-h} ${x1},${y-h}`,BLU)+MW_pl(`${x0+70},${y} ${x0+100},${y+h} ${x1},${y+h}`,BLU)
 +MW_resV(x1,y-h,y+h,GRN)+MW_L(x1,y-h,x2,y-h,INK,5)+MW_L(x1,y+h,x2,y+h,INK,5)+MW_badge(x0-18,y,'1',o.bc,o.bo)+MW_badge(x2+20,y-h,'2',o.bc,o.bo)+MW_badge(x2+20,y+h,'3',o.bc,o.bo);
/* an electron beam with dots drifting into bunches: x from x0 to x1, bunch centres every gap px; m = 0 (even) to 1 (bunched) */
