 +`<circle cx="150" cy="446" r="52" fill="#F1F3F5" stroke="${INK}" stroke-width="4"/>`
 +[0,1,2,3,4,5,6,7].map(i=>{const a=i*Math.PI/4;return `<circle cx="${(150+44*Math.cos(a)).toFixed(1)}" cy="${(446+44*Math.sin(a)).toFixed(1)}" r="8" fill="#FFFFFF" stroke="${INK}" stroke-width="2"/>`}).join('')
